from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
variants=[('CPU installed baseline','mobile_live_20261012'),('GPU only','mobile_gpu_20261012'),('GPU + automatic quality candidate','mobile_gpu_rate_20261012')]
def main():
 data=[]
 for name,folder in variants:
  d=json.loads((ROOT/'evaluation/coach_c'/folder/'results.json').read_text())
  assert d['summary']['replay_complete']==30
  data.append((name,folder,d))
 out=['# Automatic phone output improvement experiments', '', 'All variants replay the same 30 Coach C source clips once on the Xiaomi. This is development evaluation on already inspected clips, not a new independent test. Original GRU weights and 0.60 classification threshold are unchanged. All raw logs, APK hashes and exact feedback strings remain in the corresponding directories.', '', '| Variant | Classified /30 | Confident /30 | Reference-category matches among confident | Corrective/positive output /30 | No completed output | Max detected-end to UI ms |', '|---|---:|---:|---:|---:|---:|---:|']
 for name,folder,d in data:
  s=d['summary'];out.append(f"| {name} | {s['classification_available']} | {s['confident_classifications']} | {s['confident_category_agreements']}/{s['confident_classifications']} | {s['substantive_feedback']} | {30-s['clips_with_output']} | {s['gate_to_ui_max_ms']} |")
 d=data[-1][2];s=d['summary'];independent=[r for r in d['clips'] if r['status']=='CORRECTIVE' and not r['confident']]
 out += ['', '## What changed', '', '- GPU pose acquisition increases available real observations. The classifier is unchanged.', '- Motion is normalized to an 80 ms reference interval and smoothed with a 200 ms time constant, instead of measuring unnormalized displacement per frame. Tracking gaps over 500 ms reset this signal. This is a candidate automatic gate; no user recording button is added.', '- Shared mechanics rules can provide corrective advice despite uncertain classification only after at least 32 real poses spanning 1500 ms. Only existing rules explicitly applicable to all three serve types qualify. No subtype-specific paddle advice or positive overall-form judgment is generated by this fallback. The text explicitly discloses uncertain serve classification.', '', f'The candidate emitted {len(independent)} corrective outputs while classification was uncertain. This increase is partly a feedback-policy change, not improved classification accuracy. CORRECTIVE/POSITIVE indicates output availability, not proven coaching validity. Reference categories are not independent Coach C subtype ground truth.', '', '## Limits', '', 'The gate and feedback policy were changed together in the final candidate; their individual effects are not isolated. One replay per clip does not establish repeatability. GPU and CPU trials were sequential, not counterbalanced for temperature. No new clips or Coach C judgments were collected, and old ratings were not transferred to the new messages. Reuse for development limits claims about generalization.', '', 'Timing runs from automatic end detection to UI assignment. It excludes decoding/model initialization and is not an independently measured physical-serve-end-to-visible-feedback interval. Results before file end and absent results cannot be treated as proven two-second successes.', '', f"Candidate final statuses: {s['status_counts']}. Outputs before source-file end: {s['before_source_end']}; 0-2 seconds after: {s['within_0_to_2s_after_source_end']}; later than 2 seconds: {s['over_2s_after_source_end']}.", '', '## Candidate outputs', '', '| Clip | Reference | Prediction | Confidence | Real poses | Status |', '|---|---|---|---:|---:|---|']
 for r in d['clips']: out.append(f"| {r['clip']} | {r['recording_category']} | {r['prediction']} | {r['confidence']} | {r['frames']} | {r['status']} |")
 out += ['', 'Exact wording: [clip_results.csv](clip_results.csv). All intermediate events: [results.json](results.json). Tested build and source identities: [protocol.json](protocol.json).', '', '## Exact feedback', '']
 for r in d['clips']: out += [f"### {r['clip']}", '', r['feedback'] or 'No completed output.', '']
 (ROOT/'evaluation/coach_c/mobile_gpu_rate_20261012/REPORT.md').write_text('\n'.join(out),encoding='utf-8')
 print(json.dumps(dict(candidate=s,independent_mechanics_outputs=len(independent)),indent=2))
if __name__=='__main__': main()
